    if (phone.length === 10) return phone.replace(/(\d{2})(\d{4})(\d{4})/, '$1-$2-$3');
  } else if (phone.startsWith('0507') || phone.startsWith('0504') || phone.startsWith('0505') || phone.startsWith('0502') || phone.startsWith('070') || phone.startsWith('010')) {
