"const fs = require('fs');

const list = JSON.parse(fs.readFileSync('verified_200_final.json', 'utf-8'));
const niceResults = JSON.parse(fs.readFileSync('nice_200_results.json', 'utf-8'));
const ksicMap = JSON.parse(fs.readFileSync('accurate_ksic_map.json', 'utf-8'));

let niceSanupApplied = 0;
let corpNoFromNice = 0;
let repFromNice = 0;

list.forEach((r, idx) => {
  const nice = niceResults[r.bizno];
  if (nice && nice.sanupscd_kor && nice.sanupscd_kor.trim()) {
    const oldInd = r.industry;
    const newInd = nice.sanupscd_kor.trim();
    if (oldInd !== newInd) {
      r.industry = newInd;
      niceSanupApplied++;
    }
  }

  // Update categories based on accurate authoritative KSIC dictionary
  const ind = r.industry ? r.industry.trim() : '';
  if (ind && ksicMap[ind]) {
    r.catLarge = ksicMap[ind].large;
    r.catMid = ksicMap[ind].mid;
    r.catSmall = ksicMap[ind].small;
  }

  // If nice has corpNo and current record doesn't
  if (nice && nice.crpno && /^[0-9]{13}$/.test(nice.crpno.replace(/[^0-9]/g, ''))) {
    const cleanCrp = nice.crpno.replace(/[^0-9]/g, '');
    const formattedCrp = cleanCrp.slice(0, 6) + '-' + cleanCrp.slice(6);
    if (!r.corpNo) {
      r.corpNo = formattedCrp;
      r.closingMonth = '12월(추정)';
      corpNoFromNice++;
    }
  }

  // If nice has representative unmasked
  if (nice && nice.korreprnm && !nice.korreprnm.includes('*') && (!r.ceo || r.ceo.includes('*'))) {
    r.ceo = nice.korreprnm.trim();
    repFromNice++;
  }
});

console.log(`Updated records with NICE BizINFO official 산업명: ${niceSanupApplied} / ${list.length}`);
console.log(`Additional CorpNos from NICE: ${corpNoFromNice}`);
console.log(`Additional unmasked CEOs from NICE: ${repFromNice}`);

fs.writeFileSync('verified_200_final.json', JSON.stringify(list, null, 2), 'utf-8');

